from datetime import date


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        # book_id -> user currently holding it (or absent if on shelf)
        self._borrowed = {}
        # book_id -> True for every known book
        self._books = set()
        # user -> currently borrowed book_id (at most one)
        self._user_book = {}
        # user -> unpaid fine balance
        self._fines = {}

    def add_book(self, book_id: str) -> None:
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Unknown book: {book_id}")
        if book_id in self._borrowed:
            raise ValueError(f"Book already borrowed: {book_id}")
        if user in self._user_book:
            raise ValueError(f"User already holds a book: {user}")
        self._borrowed[book_id] = (user, day)
        self._user_book[user] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if self._user_book.get(user) != book_id:
            raise ValueError(f"User {user} has not borrowed book {book_id}")
        _, borrow_day = self._borrowed.pop(book_id)
        del self._user_book[user]

        due = borrow_day.toordinal() + self.loan_days
        delay = day.toordinal() - due
        fine = 0.0
        if delay > 0:
            fine = delay * self.daily_fine
            self._fines[user] = self._fines.get(user, 0.0) + fine
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self._fines[user] = 0.0
